// Go: pagination loop with context cancellation
ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
defer cancel()
pageTok := ""
for {
    resp, err := client.ListEmbeddings(ctx, &ListRequest{PageToken: pageTok, PageSize: 200})
    if err != nil { return err }
    for _, item := range resp.Items { fmt.Println(item.Id) }
    if resp.NextPageToken == "" { break }
    pageTok = resp.NextPageToken
}
